/**
 * build-notification.js
 *
 * Called by the "notify-completion" GitHub Actions workflow.
 * Fetches pull-request data and creates:
 *   - A GitHub issue notifying the repo owner that the project is ready for review
 *   - (Optional) Returns the HTML body string for an email notification
 *
 * Required environment variables (injected by the workflow):
 *   GITHUB_TOKEN   – automatically provided by Actions
 *   CUSTOM_MSG     – optional extra message (from workflow_dispatch input)
 */

module.exports = async ({ github, context, core }) => {
  const owner = context.repo.owner;
  const repo  = context.repo.repo;

  // ── 1. Collect pull-request information ────────────────────────────────────
  const { data: pulls } = await github.rest.pulls.list({
    owner,
    repo,
    state:     'all',
    per_page:  10,
    sort:      'updated',
    direction: 'desc',
  });

  const prTableRows = pulls.length
    ? pulls.map(pr => {
        const status = pr.merged_at
          ? '✅ Merged'
          : pr.state === 'open'
            ? '🟡 Open'
            : '❌ Closed';
        return `| [#${pr.number} – ${pr.title}](${pr.html_url}) | ${status} |`;
      })
    : ['| No pull requests found. | – |'];

  const { data: repoData } = await github.rest.repos.get({ owner, repo });

  const actor     = context.eventName === 'pull_request'
                    ? context.payload.pull_request.user.login
                    : context.actor;
  const repoUrl   = repoData.html_url;
  const repoName  = repoData.full_name;
  const repoShort = repo;
  const timestamp = new Date().toUTCString();
  const customMsg = process.env.CUSTOM_MSG || '';

  // ── 2. Build issue body ────────────────────────────────────────────────────
  const customSection = customMsg
    ? `\n## 💬 Additional Notes\n\n${customMsg}\n`
    : '';

  const prTable = prTableRows.join('\n');

  const issueBody = [
    '## 🎉 Project Ready for Review and Testing',
    '',
    `Hello @${actor}!`,
    '',
    `The **[${repoName}](${repoUrl})** cloud-infrastructure project has been`,
    'completed and is now ready for your review and testing.',
    '',
    '---',
    '',
    '## 📊 Project Status',
    '',
    '| Item | Status |',
    '|------|--------|',
    '| Design & implementation | ✅ Complete |',
    '| Code pushed to repository | ✅ Done |',
    '| Ready for review & testing | ✅ Yes |',
    customSection,
    '---',
    '',
    '## 🔗 Pull Requests',
    '',
    '| Pull Request | Status |',
    '|--------------|--------|',
    prTable,
    '',
    '---',
    '',
    '## 🧪 Testing Instructions',
    '',
    '### 1 · Clone the repository',
    '```bash',
    `git clone ${repoUrl}.git`,
    `cd ${repoShort}`,
    '```',
    '',
    '### 2 · Review pull requests',
    'Browse the pull requests listed above. Each one contains detailed',
    'implementation notes and change descriptions.',
    '',
    '### 3 · Deploy and test',
    'Follow any deployment instructions in the repository (e.g., `README.md` or',
    'the docs folder) to spin up the infrastructure locally or in your cloud',
    'environment.',
    '',
    '### 4 · Provide feedback',
    'Leave your feedback as comments directly on the relevant pull requests or',
    'open new issues in this repository.',
    '',
    '---',
    '',
    `*This notification was automatically generated by GitHub Actions on ${timestamp}.*`,
  ].join('\n');

  // ── 3. Ensure required labels exist ───────────────────────────────────────
  const labels = [
    { name: 'notification',     color: '0075ca', description: 'Automated notification' },
    { name: 'ready-for-review', color: '0e8a16', description: 'Ready for review and testing' },
  ];

  for (const label of labels) {
    try {
      await github.rest.issues.getLabel({ owner, repo, name: label.name });
    } catch (err) {
      if (err.status === 404) {
        await github.rest.issues.createLabel({
          owner,
          repo,
          name:        label.name,
          color:       label.color,
          description: label.description,
        });
        core.info(`Created label: ${label.name}`);
      } else {
        throw err;
      }
    }
  }

  // ── 4. Create the notification issue ──────────────────────────────────────
  const { data: issue } = await github.rest.issues.create({
    owner,
    repo,
    title:  `✅ [Notification] ${repoName} is ready for review and testing`,
    body:   issueBody,
    labels: ['notification', 'ready-for-review'],
  });

  core.info(`GitHub notification issue created: ${issue.html_url}`);

  // ── 5. Export outputs for the email step ──────────────────────────────────
  core.setOutput('issue_url', issue.html_url);
  core.setOutput('repo_url',  repoUrl);
  core.setOutput('repo_name', repoName);
  core.setOutput('actor',     actor);
  core.setOutput('timestamp', timestamp);
};
